const API_TOKEN = process.env.POEDITOR_API_TOKEN;
const PROJECT_ID = process.env.POEDITOR_PROJECT_ID;
if (!API_TOKEN || !PROJECT_ID) {
  console.error('POEDITOR_API_TOKEN and POEDITOR_PROJECT_ID must be set');
  process.exit(1);
}

if (
  formattedTranslations === null ||
  typeof formattedTranslations !== 'object' ||
  Array.isArray(formattedTranslations) ||
  Object.keys(formattedTranslations).length === 0
) {
  throw new Error(`Unexpected or empty payload for ${language}, refusing to overwrite the locale file: ${JSON.stringify(formattedTranslations).slice(0, 200)}`);
}

await fs.writeJson(outputPath, formattedTranslations, { spaces: 2 });
